"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[67795],{25239:e=>{e.exports=JSON.parse('{"month":"2026-08","entries":[{"id":"2026-08-26-converse-2-0-api-documentation","date":"2026-08-26","products":["Converse"],"product":"Converse","channel":"","changeType":"Added","title":"Converse 2.0 API documentation, now at its own /converse section","excerpt":"Converse now has full API documentation, and its own top-level section on the developer portal \u2014 no longer nested under Connect.","hasArticle":true},{"id":"2026-08-07-viber-message-templates","date":"2026-08-07","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Viber message templates","excerpt":"You can now create and manage Viber message templates \u2014 pre-approved message formats for transactional messages and OTPs, with dynamic {{parameter}} placeholders substituted at send time. Creating templates requires an admin role on the account.","hasArticle":true},{"id":"2026-08-06-alerting-rt-scope-clarified","date":"2026-08-06","products":["Analytics"],"product":"Analytics","channel":"","changeType":"Changed","title":"alerting.rt scope clarified","excerpt":"The Real-Time Statistics documentation now spells out exactly what the alerting.rt metric counts and what it excludes, so it is interpreted consistently. This is a documentation clarification \u2014 there is no change to the metric\'s behaviour.","hasArticle":true},{"id":"2026-08-05-rcs-attribution-corrected","date":"2026-08-05","products":["Connect"],"product":"Connect","channel":"RCS","changeType":"Fixed","title":"RCS attribution corrected","excerpt":"The RCS guide previously described Rich Communication Services as \\"a protocol developed by Google.\\" That was inaccurate, and it is now corrected.","hasArticle":true},{"id":"2026-08-04-bridge-adapter-endpoint-for-sapi-migration","date":"2026-08-04","products":["Actions & Events"],"product":"Actions & Events","channel":"Streaming","changeType":"Added","title":"Bridge adapter endpoint for SAPI migration","excerpt":"The Streaming API migration guide now documents a backwards-compatible adapter (Bridge) endpoint \u2014 a second migration path for existing Streaming API integrations that cannot move to the Pulsar API directly.","hasArticle":true},{"id":"2026-08-04-templateid-in-direct-send-delivery-receipts","date":"2026-08-04","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"templateId in Direct Send delivery receipts","excerpt":"WhatsApp delivery receipts now include a templateId field for messages sent via the WhatsApp Direct Send API, so you can correlate a receipt back to the exact template that was delivered.","hasArticle":true},{"id":"2026-08-03-line-channel-documentation","date":"2026-08-03","products":["Connect"],"product":"Connect","channel":"LINE","changeType":"Added","title":"LINE channel documentation","excerpt":"The full LINE channel documentation is now published. LINE is the most popular chat app in Japan, Thailand, and Taiwan, and it reaches users through the same 8x8 Messaging Apps API and webhook envelope you already use for SMS, WhatsApp, Viber, and RCS.","hasArticle":true}]}')}}]);